/**
 * Gemini Pitch Post-Processor & Enforcer (Run Once for Each Item)
 * Uses n8n paired item resolution so filtered items never misalign.
 * Strictly enforces Requirement 7: Exactly one sentence.
 */
const orig = $('Normalize Profile Data').item.json;
const rawCandidate = $json?.candidates?.[0]?.content?.parts?.[0]?.text || '';

let cleaned = rawCandidate
  .replace(/^[\"'`\s]+|[\"'`\s]+$/g, '')
  .replace(/\*\*/g, '')
  .replace(/\n+/g, ' ')
  .replace(/^(Here is (why|the|a).*?:|Why they are a lead:|Lead analysis:|Reason:)\s*/i, '')
  .trim();

// Extract strictly the first complete sentence
const sentenceMatch = cleaned.match(/^([^.!?]+[.!?])/);
if (sentenceMatch && sentenceMatch[1]) {
  cleaned = sentenceMatch[1].trim();
} else if (cleaned.length > 0 && !/[.!?]$/.test(cleaned)) {
  cleaned += '.';
}

// Safe fallback if LLM response is empty or invalid
if (!cleaned) {
  const title = orig.company && orig.company !== 'Not specified' ? `at ${orig.company}` : 'in the developer ecosystem';
  cleaned = `${orig.name || orig.login} is a high-impact engineer ${title} with ${orig.followers} followers and ${orig.public_repos} public repositories.`;
}

return {
  json: {
    ...orig,
    ai_pitch: cleaned
  }
};

/**
 * Format Discord Rich Embed (Run Once for Each Item)
 * Formats the qualified lead and Gemini pitch into a structured Discord embed
 */
const lead = $json;
const config = $('Config').first().json;

const payload = {
  username: 'Lead Sniper Bot',
  avatar_url: 'https://cdn-icons-png.flaticon.com/512/3242/3242257.png',
  embeds: [
    {
      title: `🎯 High-Value GitHub Lead: @${lead.login}`,
      url: lead.html_url || `https://github.com/${lead.login}`,
      color: 3066993,
      author: {
        name: `${lead.name || lead.login} (@${lead.login})`,
        url: lead.html_url || `https://github.com/${lead.login}`,
        icon_url: lead.avatar_url || ''
      },
      thumbnail: {
        url: lead.avatar_url || ''
      },
      description: `💡 **AI Lead Angle:**\n${lead.ai_pitch}`,
      fields: [
        {
          name: '🏢 Company',
          value: lead.company && lead.company !== 'Not specified' ? lead.company : 'Not specified',
          inline: true
        },
        {
          name: '👥 Followers',
          value: String(lead.followers ?? 0),
          inline: true
        },
        {
          name: '📦 Public Repos',
          value: String(lead.public_repos ?? 0),
          inline: true
        },
        {
          name: '📍 Location',
          value: lead.location && lead.location !== 'Remote / Unspecified' ? lead.location : 'Remote / Unspecified',
          inline: true
        },
        {
          name: '📝 Bio',
          value: lead.bio && lead.bio !== 'Not specified' ? lead.bio : 'No bio provided',
          inline: false
        }
      ],
      footer: {
        text: `Lead Sniper • Target: ${config.githubOwner}/${config.githubRepo}`
      },
      timestamp: new Date().toISOString()
    }
  ]
};

return {
  json: {
    ...lead,
    discord_payload: payload
  }
};

/**
 * Audit Log & State Confirmation Node (Run Once for Each Item)
 * Confirms delivery of each individual lead via paired item reference
 */
const lead = $('Format Discord Embed').item.json;
return {
  json: {
    status: 'NOTIFIED',
    dispatched_at: new Date().toISOString(),
    starred_at: lead.starred_at,
    lead_id: lead.id,
    login: lead.login,
    followers: lead.followers,
    public_repos: lead.public_repos,
    company: lead.company,
    ai_pitch: lead.ai_pitch
  }
};

/**
 * Global Error Handler Node
 * Captures uncaught runtime failures and logs actionable diagnostic context
 */
const errorData = $json;
console.error('Lead Sniper Execution Failure:', JSON.stringify(errorData, null, 2));
return [{
  json: {
    status: 'EXECUTION_ERROR',
    timestamp: new Date().toISOString(),
    message: errorData.execution?.error?.message || 'Unknown error occurred',
    failed_node: errorData.execution?.lastNodeExecuted || 'Unknown'
  }
}];
